def need(ok, msg):
    if not ok: raise RuntimeError(msg)
def ident(raw):
    return {"bytes":len(raw),"sha256":hashlib.sha256(raw).hexdigest()}
def encode(v):
    return (json.dumps(v,sort_keys=True,indent=2)+"\n").encode()
def read(path, expected=None):
    path=Path(path)
    need(path.is_absolute() and path.resolve(strict=True)==path,"indirect input "+str(path))
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    with os.fdopen(fd,"rb") as f:
        a=os.fstat(f.fileno())
        need(stat.S_ISREG(a.st_mode) and a.st_nlink==1 and 0<=a.st_size<=16*1024*1024,"unsafe input "+str(path))
        raw=f.read(a.st_size+1)
        b=os.fstat(f.fileno())
    c=path.lstat()
    fields=("st_dev","st_ino","st_mode","st_uid","st_nlink","st_size","st_mtime_ns","st_ctime_ns")
    need(len(raw)==a.st_size and all(getattr(a,k)==getattr(b,k)==getattr(c,k) for k in fields),"changed input "+str(path))
    if expected is not None: need(ident(raw)=={k:expected[k] for k in ("bytes","sha256")},"identity mismatch "+str(path))
    return raw
def create(path,raw):
    need(path.parent.resolve(strict=True)==path.parent,"indirect destination")
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
    with os.fdopen(fd,"wb") as f:
        f.write(raw); f.flush(); os.fsync(f.fileno())
    read(path,ident(raw))
    return {"path":str(path),**ident(raw)}
